// Real roof-window model library (producer + model code -> required blind
// dimensions), sourced live from the CRM's public roof-window library
// endpoint (biuro/api/allegro/roof_windows_public.php), the exact same
// dataset the real /dachowe-family configurators search against - fetched
// and embedded 2026-08-30 (420 real entries: Velux, Fakro, Roto, OKPOL,
// Dakstra, Optilight). Not invented; a periodic re-sync from that endpoint
// is the way to keep this current if new models are added there.
//
// windowWidthMm/windowHeightMm: the nominal window size code as printed on
// the window's own nameplate/spec sheet.
// blindWidthMm/blindHeightMm: the actual size the roller blind itself needs
// to be manufactured to for that window - this is what rolety-dachowe is
// actually priced/sized by (flat price regardless of size, per shared.ts).
// certain: false means the CRM's own library flags this measurement as not
// independently verified - shown to the customer as a small caveat, not
// hidden.
export type RoofWindowModel = {
  producer: string;
  model: string;
  altModel: string;
  windowWidthMm: number;
  windowHeightMm: number;
  blindWidthMm: number;
  blindHeightMm: number;
  certain: boolean;
};

